-- 0026 DrawUp V19 directory data: KEi admins, firm websites and offices from public research,
-- and the three showcase projects with their teams and sources. Additive and safe to run again.

-- Helpers used by the DrawUp directory data files. Run by the SQL editor only.
create or replace function public.drawup_import_firm(p jsonb) returns text
language plpgsql set search_path = public as $$
declare v_id uuid; o jsonb; v_ex uuid; v_hq boolean; v_conf boolean := coalesce((p->>'confirmed')::boolean,false); v_c text;
begin
  select id into v_id from firms where slug = p->>'slug';
  if v_id is null then v_id := public.drawup_match_firm(p->>'name'); end if;
  if v_id is null and coalesce((p->>'create')::boolean,false) then
    insert into firms(slug, name, is_verified, is_demo, discipline) values (p->>'slug', p->>'name', false, false, p->>'discipline')
    on conflict (slug) do nothing;
    select id into v_id from firms where slug = p->>'slug';
  end if;
  if v_id is null then return 'skipped (not in directory): ' || (p->>'name'); end if;
  update firms set website = coalesce(nullif(website,''), p->>'website'),
    description = coalesce(nullif(description,''), p->>'description'),
    discipline = coalesce(nullif(discipline,''), p->>'discipline'),
    founded_year = coalesce(founded_year, (p->>'founded')::int),
    source_url = coalesce(source_url, p->>'source'), research_note = coalesce(p->>'note', research_note)
  where id = v_id;
  for o in select * from jsonb_array_elements(coalesce(p->'offices','[]'::jsonb)) loop
    v_hq := coalesce((o->>'hq')::boolean,false); v_c := coalesce(o->>'country','US');
    select x.id into v_ex from firm_offices x where x.firm_id = v_id and lower(x.city) = lower(o->>'city')
      and coalesce(lower(x.state),'') = coalesce(lower(o->>'state'),'')
      and case when v_c = 'US' then lower(coalesce(x.country,'US')) in ('us','usa','united states','united states of america')
               else lower(x.country) = lower(v_c) end limit 1;
    if v_hq and v_conf then  -- the firm's own site names its HQ: earlier unconfirmed HQ guesses step aside
      update firm_offices set is_headquarters = false where firm_id = v_id and is_headquarters and not is_confirmed
        and id is distinct from v_ex;
    end if;
    if v_ex is null then
      insert into firm_offices(firm_id, city, state, country, is_headquarters, address, phone, source, source_url, is_confirmed)
      values (v_id, o->>'city', o->>'state', v_c, v_hq, o->>'address', o->>'phone', 'public_research', p->>'source', v_conf);
    else
      update firm_offices set address = coalesce(address, o->>'address'), phone = coalesce(phone, o->>'phone'),
        is_headquarters = is_headquarters or (v_hq and v_conf), source_url = coalesce(source_url, p->>'source'),
        is_confirmed = is_confirmed or v_conf where id = v_ex;
    end if;
  end loop;
  return 'ok';
end $$;
revoke all on function public.drawup_import_firm(jsonb) from public, anon, authenticated;

create or replace function public.drawup_import_project(p jsonb) returns text
language plpgsql set search_path = public as $$
declare v_id uuid; t jsonb; v_f uuid; s jsonb;
begin
  insert into aec_projects(slug, name, city, state, country, project_type, status, is_demo)
  values (p->>'slug', p->>'name', p->>'city', p->>'state', coalesce(p->>'country','US'), p->>'project_type', p->>'status', false)
  on conflict (slug) do nothing;
  select id into v_id from aec_projects where slug = p->>'slug';
  update aec_projects set description = coalesce(nullif(description,''), p->>'description'),
    completion_year = coalesce(completion_year, (p->>'completion_year')::int), opened_year = coalesce(opened_year, (p->>'opened_year')::int),
    street_address = coalesce(street_address, p->>'street_address'), owner_name = coalesce(owner_name, p->>'owner_name'),
    cost_text = coalesce(cost_text, p->>'cost_text'), capacity_text = coalesce(capacity_text, p->>'capacity_text'),
    size_text = coalesce(size_text, p->>'size_text'), image_page_url = coalesce(image_page_url, p->>'image_page_url'),
    key_facts = case when key_facts = '[]'::jsonb then coalesce(p->'key_facts','[]'::jsonb) else key_facts end,
    conflicts = case when conflicts = '[]'::jsonb then coalesce(p->'conflicts','[]'::jsonb) else conflicts end
  where id = v_id;
  for t in select * from jsonb_array_elements(coalesce(p->'team','[]'::jsonb)) loop
    select id into v_f from firms where slug = t->>'slug';
    if v_f is not null and not exists (select 1 from project_firms where project_id = v_id and firm_id = v_f and role = t->>'role') then
      insert into project_firms(project_id, firm_id, role, provenance) values (v_id, v_f, t->>'role', 'public_source');
    end if;
  end loop;
  for t in select * from jsonb_array_elements(coalesce(p->'people','[]'::jsonb)) loop
    if not exists (select 1 from project_people where project_id = v_id and name = t->>'name') then
      insert into project_people(project_id, name, role, provenance) values (v_id, t->>'name', t->>'role', 'public_source');
    end if;
  end loop;
  for s in select * from jsonb_array_elements(coalesce(p->'sources','[]'::jsonb)) loop
    if not exists (select 1 from project_sources where project_id = v_id and source_url = s->>'url') then
      insert into project_sources(project_id, source_name, source_url) values (v_id, s->>'name', s->>'url');
    end if;
  end loop;
  for t in select * from jsonb_array_elements(coalesce(p->'tags','[]'::jsonb)) loop
    if not exists (select 1 from project_tags where project_id = v_id and tag = t#>>'{}') then
      insert into project_tags(project_id, tag) values (v_id, t#>>'{}');
    end if;
  end loop;
  return 'ok: ' || (p->>'name');
end $$;
revoke all on function public.drawup_import_project(jsonb) from public, anon, authenticated;

-- KEi Architects admins (founder + personal account)
insert into public.firm_members(firm_id, user_id, role)
select f.id, u.id, 'admin' from public.firms f
join public.profiles u on u.id in ('486dcfbf-0858-4dfd-b43d-559818b21127','3758a6e0-1b49-485d-a8b6-5b16e0012aa1')
where f.slug = 'kei-architects' or f.id = public.drawup_match_firm('KEi Architects')
on conflict (firm_id, user_id) do update set role = 'admin';

