-- Showcase projects
select public.drawup_import_project('{"slug":"state-farm-arena","name":"State Farm Arena","city":"Atlanta","state":"GA","project_type":"Arena renovation","status":"Completed","street_address":"1 State Farm Drive, Atlanta, GA","opened_year":1999,"completion_year":2018,"owner_name":"Atlanta Fulton County Recreation Authority (operated by the Atlanta Hawks)","cost_text":"$192.5 million renovation (2017-2018); original arena $213.5 million (1999)","capacity_text":"17,608 for basketball (about 18,000 for concerts)","size_text":"780,000 sq ft renovation scope (Thornton Tomasetti); 680,000 sq ft building (Wikipedia)","image_page_url":"https://www.hok.com/projects/view/state-farm-arena/","description":"State Farm Arena is the home of the NBA''s Atlanta Hawks in downtown Atlanta. It opened in 1999 and was given a $192.5 million renovation designed by HOK, finished in October 2018. The work redesigned the concourses, suites and amenities while keeping the arena in use.","key_facts":["Renovation cost $192.5 million and was finished in October 2018 (HOK).","HOK designed the renovation; Thornton Tomasetti was the structural engineer, as it was for the original 1999 arena (Thornton Tomasetti).","Four concrete columns holding the roof trusses were removed and replaced by a new transfer truss spanning about 175 feet (Thornton Tomasetti).","Over 100,000 sq ft of office and storage space was turned into fan spaces, including restaurants, a barber shop and virtual golf suites (Thornton Tomasetti).","Added the NBA''s first courtside bar and a 4,477 sq ft center-hung scoreboard (HOK).","Owned by the Atlanta Fulton County Recreation Authority and operated by the Atlanta Hawks (Wikipedia)."],"conflicts":["Capacity: 17,608 (Wikipedia) vs ~17,000 (HOK).","Size: 780,000 sq ft (Thornton Tomasetti, renovation scope) vs 680,000 sq ft (Wikipedia)."],"sources":[{"name":"HOK: Atlanta Hawks Celebrate Completion of HOK-Designed State Farm Arena Transformation","url":"https://hok.com/news/2018-10/atlanta-hawks-celebrate-completion-of-hok-designed-state-farm-arena-transformation"},{"name":"Thornton Tomasetti: State Farm Arena Renovation","url":"https://thorntontomasetti.com/project/state-farm-arena-renovation"},{"name":"Wikipedia: State Farm Arena","url":"https://en.wikipedia.org/wiki/State_Farm_Arena"}],"tags":["Arena","Sports","Renovation","NBA"],"team":[{"slug":"hok","role":"Architect (renovation)"},{"slug":"thornton-tomasetti","role":"Structural engineer (renovation and original 1999 arena)"},{"slug":"populous","role":"Architect (original 1999 arena, as HOK Sport)"},{"slug":"arquitectonica","role":"Architect (original 1999 arena)"}],"people":[{"name":"Atlanta Arena Constructors (joint venture)","role":"General contractor (original 1999 arena)"}]}'::jsonb);
select public.drawup_import_project('{"slug":"bank-of-america-stadium","name":"Bank of America Stadium","city":"Charlotte","state":"NC","project_type":"Stadium","status":"Open; major renovation planned","street_address":"800 South Mint Street, Charlotte, NC","opened_year":1996,"owner_name":"Tepper Sports & Entertainment","cost_text":"$248 million original (StadiumDB); $800 million renovation planned","capacity_text":"75,037 (Wikipedia); 74,867 for NFL games (StadiumDB)","image_page_url":null,"description":"Bank of America Stadium is an open-air football stadium in uptown Charlotte that opened in 1996 for the Carolina Panthers and has hosted Charlotte FC since 2022. An $800 million renovation designed by HOK is planned, with Clark Construction and D.A. Everett as contractors.","key_facts":["Opened in 1996 as Ericsson Stadium; renamed Bank of America Stadium in 2004 (Wikipedia).","Original architects were Populous (then HOK Sport) and Wagner Murray Architects; built by Turner and F.N. Thompson (Wikipedia; StadiumDB).","Original construction cost was reported as $248 million (StadiumDB).","Charlotte City Council approved up to $650 million toward an $800 million renovation; Tepper Sports & Entertainment covers the rest and any overruns (ENR).","The Panthers agreed to a 20-year lease keeping the team in Charlotte through 2045 (ENR).","HOK''s design adds metal bands over the concrete arches, a glass-clad exterior and new public plazas; the stadium stays open during the work (Dezeen).","Hybrid turf was installed in 2021 for soccer (StadiumDB)."],"conflicts":["Original cost: StadiumDB says $248 million; the Wikipedia summary said $500 million (likely inflation-adjusted, not checked). Use $248 million.","Renovation start: 2026 (ENR) vs 2027 groundbreaking (Dezeen, July 2026).","Capacity: 75,037 (Wikipedia) vs 74,867 / 75,412 (StadiumDB)."],"sources":[{"name":"Wikipedia: Bank of America Stadium","url":"https://en.wikipedia.org/wiki/Bank_of_America_Stadium"},{"name":"StadiumDB: Bank of America Stadium (Carolinas Stadium)","url":"https://stadiumdb.com/stadiums/usa/bank_of_america_stadium"},{"name":"ENR: Charlotte Approves $800M Panthers Stadium Renovation","url":"https://www.enr.com/articles/61970-charlotte-approves-800m-stadium-renovation"},{"name":"Dezeen: HOK design for Panthers stadium renovation","url":"https://www.dezeen.com/2026/07/30/hok-carolina-panthers-nfl-stadium-charlotte/amp/"}],"tags":["Stadium","Sports","NFL","MLS"],"team":[{"slug":"populous","role":"Architect (original 1996 stadium, as HOK Sport)"},{"slug":"wagner-murray-architects","role":"Architect (original 1996 stadium)"},{"slug":"bliss-and-nyitray","role":"Structural engineer (original)"},{"slug":"turner-construction","role":"General contractor (original, with F.N. Thompson)"},{"slug":"hok","role":"Architect (planned renovation)"},{"slug":"clark-construction-group","role":"Contractor (planned renovation)"},{"slug":"d-a-everett-construction-group","role":"Contractor (planned renovation)"}],"people":[{"name":"F.N. Thompson","role":"General contractor (original, with Turner)"},{"name":"CAA Icon","role":"Owner''s representative (planned renovation)"}]}'::jsonb);
select public.drawup_import_project('{"slug":"sofi-stadium","name":"SoFi Stadium","city":"Inglewood","state":"CA","project_type":"Stadium","status":"Completed","street_address":"1001 South Stadium Drive, Inglewood, CA","opened_year":2020,"completion_year":2020,"owner_name":"StadCo LA / Hollywood Park Land Company (Stan Kroenke)","cost_text":"$5-6 billion (estimated, Wikipedia)","capacity_text":"70,240 standard, expandable to 100,000+","size_text":"3.1 million sq ft stadium on the 298-acre Hollywood Park site","image_page_url":"https://www.hksinc.com/our-projects/sofi-stadium/","description":"SoFi Stadium is the shared home of the Los Angeles Rams and Chargers, built on the former Hollywood Park racetrack site in Inglewood. Designed by HKS and opened in 2020, it sits under a translucent ETFE roof canopy that also covers a performance venue and a public plaza.","key_facts":["Opened on September 8, 2020 (Wikipedia).","About 70,000 fixed seats, expandable to 100,000 for major events (HKS).","The stadium covers 3.1 million sq ft, the largest in the NFL (HKS).","The seating bowl sits about 100 feet below grade (HKS).","The roof canopy uses ETFE panels, some of which open for ventilation (Wikipedia; HKS).","The 2.2-million-pound, 120-yard-long video board is a signature feature (AIA).","Includes 260 suites, about 13,000 premium seats and a 6,000-seat performance venue under the same canopy (HKS).","Built on a 298-acre site with about 25 acres of public space (AIA)."],"conflicts":["Capacity: 70,240 (Wikipedia) vs about 70,000 fixed seats (HKS)."],"sources":[{"name":"HKS: SoFi Stadium","url":"https://www.hksinc.com/our-projects/sofi-stadium/"},{"name":"American Institute of Architects: SoFi Stadium and Hollywood Park","url":"https://www.aia.org/design-excellence/award-winners/sofi-stadium-and-hollywood-park"},{"name":"Wikipedia: SoFi Stadium","url":"https://en.wikipedia.org/wiki/SoFi_Stadium"}],"tags":["Stadium","Sports","NFL","ETFE roof"],"team":[{"slug":"hks","role":"Archi